import web.helpers.clipByCorner
import web.helpers.padding
import web.theme.JsMainTheme
import web.views.JsTextView
import web.views.Spacer


@Composable
fun JsInfoGenderItem(
    title: String,
    text: String
) {
    Column(modifier = Modifier.fillMaxWidth().padding(start = 16.px, end = 16.px, top = 16.px)) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Box(
                modifier = Modifier.size(8.px).clipByCorner()
                    .background(color = JsMainTheme.colors.app_main_color)
            )

            Spacer(modifier = Modifier.width(8.px))
            JsTextView(
                modifier = Modifier.weight(1f), textSize = 14,
                text = title,
                fontWeight = FontWeight.Medium
            )
        }

        Spacer(modifier = Modifier.height(4.px))

        JsTextView(text = text, textSize = 14)
    }
}