data class MultiSelectItem(var itemTitle: String, var onSelected: Boolean = false)

@Composable
fun ButtonsMultiSelect(
    itemsFlow: StateFlow<List<MultiSelectItem>>,
    modifier: Modifier = Modifier,
    onClick: (MultiSelectItem) -> Unit
) {
    val itemsState = itemsFlow.collectAsState()
    LazyColumn(
        modifier = modifier,
        contentPadding = PaddingValues(top = 24.dp, bottom = 20.dp),
        verticalArrangement = Arrangement.spacedBy(24.dp)
    ) {
        itemsIndexed(itemsState.value) { index, item ->
            val color = backgroundItemColor(itemsState.value.size, index)
            MultiSelectItem(item, color, onClick)
        }
    }
}

@Composable
private fun MultiSelectItem(
    item: MultiSelectItem,
    color: Color,
    onClick: (MultiSelectItem) -> Unit
) {
    Card(
        modifier = Modifier
            .fillMaxWidth(0.8f)
            .clickable {
                onClick.invoke(item)
            },
        backgroundColor = if (item.onSelected) color else MainTheme.colors.main_color_background,
        shape = RoundedCornerShape(30.dp),
        border = BorderStroke(
            if (item.onSelected) 0.dp else 2.dp,
            color = if (item.onSelected) color else color.copy(alpha = 0.5f)
        )
    ) {
        Box(modifier = Modifier.fillMaxSize()) {
            if (item.onSelected) {
                CustomImageView(
                    Res.drawable.ic_onboarding_select_accept,
                    modifier = Modifier
                        .padding(start = 24.dp)
                        .align(Alignment.CenterStart)
                )
            }

            Text(
                text = item.itemTitle,
                modifier = Modifier
                    .fillMaxWidth()
                    .align(Alignment.Center)
                    .padding(vertical = 12.dp),
                color = MainTheme.colors.text_color_default,
                fontSize = 15.sp,
                fontWeight = FontWeight.Medium,
                textAlign = TextAlign.Center
            )
        }
    }
}

@Composable
fun backgroundItemColor(size: Int, position: Int): Color = when (position) {
    0 -> if (size > 2) MainTheme.colors.bg_color_onboarding_item_1 else MainTheme.colors.main_color_item_3
    1 -> if (size > 2) MainTheme.colors.bg_color_onboarding_item_2 else MainTheme.colors.app_main_color
    2 -> MainTheme.colors.bg_color_onboarding_item_3
    3 -> MainTheme.colors.bg_color_onboarding_item_4
    4 -> MainTheme.colors.bg_color_onboarding_item_5
    5 -> MainTheme.colors.bg_color_onboarding_item_6
    6 -> MainTheme.colors.bg_color_onboarding_item_7
    else -> MainTheme.colors.bg_color_onboarding_item_8

}