package managers

sealed class ShowAlertState {
    data object Hide : ShowAlertState()
    data object SomethingWrongError : ShowAlertState()

    data class ShowDefaultDialog<T : Any, R : Any?>(val title: T, val message: R?) :
        ShowAlertState()

    data class ShowErrorMessage(val message: String?) : ShowAlertState()

    data class ShowOkCancelDialog(
        val title: String,
        val message: String?,
        val okText: String,
        val cancelText: String,
        val dismissOnClickOutside: Boolean = false,
        val withCloseButton: Boolean = false,
        val onOkClick: () -> Unit,
        val onCancelClick: () -> Unit = {}
    ) : ShowAlertState()

    data class ShowInputTextDialog(
        val title: String,
        val message: String?,
        val inputPlaceholder: String,
        val okText: String,
        val cancelText: String,
        val dismissOnClickOutside: Boolean = false,
        val onOkClick: (String?) -> Unit
    ) : ShowAlertState()

    data class AlertByType(
        val alertType: AlertType,
        val dismissOnClickOutside: Boolean = false,
        val withCloseButton: Boolean = false,
        val onOkClick: () -> Unit,
        val onCancelClick: () -> Unit = {}
    ) : ShowAlertState()
}

enum class AlertType {
    Default, Logout, DeleteAccount
}