@Composable
fun JsDefaultAlert(
    title: String? = null,
    message: String? = null,
    positiveButtonText: String = stringResource(Res.string.dialog_btn_ok),
    negativeButtonText: String? = null,
    dismissOnBackPress: Boolean = false,
    dismissOnClickOutside: Boolean = false,
    withCloseButton: Boolean = false,
    inputFieldPlaceholder: String? = null,
    onPositiveClick: (String?) -> Unit = {},
    onNegativeClick: () -> Unit = {},
    onDismiss: () -> Unit,
) {
    val inputValue = remember { mutableStateOf<String?>(null) }

    @Composable
    fun buttonsRow() {
        val cornerShape = 6
        val buttonHeight = 40.px

        Spacer(modifier = Modifier.height(24.px))
        Row(
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.fillMaxWidth()
        ) {
            negativeButtonText?.let {
                Box(
                    Modifier.weight(1f).height(buttonHeight).clipByCorner(cornerShape)
                        .border(1.px, style = LineStyle.Solid, JsMainTheme.colors.app_main_color)
                        .clickable {
                            onNegativeClick()
                            onDismiss()
                        }, contentAlignment = Alignment.Center
                ) {
                    JsTextView(
                        text = it, 14,
                        modifier = Modifier.padding(horizontal = 6.px, vertical = 8.px),
                        textColor = JsMainTheme.colors.app_main_color,
                        textAlign = TextAlign.Center, maxLines = 1
                    )
                }
                Spacer(modifier = Modifier.size(8.px))
            }
            Box(
                Modifier.weight(1f).height(buttonHeight).clipByCorner(cornerShape)
                    .background(JsMainTheme.colors.app_main_color)
                    .clickable {
                        onPositiveClick(inputValue.value)
                        onDismiss()
                    }, contentAlignment = Alignment.Center
            ) {
                JsTextView(
                    text = positiveButtonText, 14,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.padding(horizontal = 6.px, vertical = 8.px),
                    textColor = Colors.White,
                    textAlign = TextAlign.Center, maxLines = 1
                )
            }
        }
    }

    Box(
        modifier = Modifier.fillMaxSize()
            .background(JsMainTheme.colors.main_color_black_transparent_70)
            .onClick { if (dismissOnClickOutside) onDismiss() },
        contentAlignment = Alignment.Center
    ) {
        Box(
            Modifier.fillMaxWidth().padding(horizontal = 32.px),
            contentAlignment = Alignment.Center
        ) {
            Column(
                modifier = Modifier.clipByCorner(12)
                    .background(JsMainTheme.colors.main_color_background)
                    .onClick { event -> event.stopPropagation() }
                    .padding(start = 16.px, end = 16.px, top = 24.px, bottom = 16.px),
                verticalArrangement = Arrangement.Center,
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                title?.let {
                    JsTextView(
                        text = title, 16,
                        fontWeight = FontWeight.SemiBold,
                        textColor = JsMainTheme.colors.text_color_default,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.padding(horizontal = 8.px)
                    )
                }
                if (!title.isNullOrEmpty() && !message.isNullOrEmpty())
                    Spacer(modifier = Modifier.height(10.px))
                message?.let {
                    JsTextView(
                        text = it, 14,
                        textColor = JsMainTheme.colors.text_color_gray,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.padding(horizontal = 8.px)
                    )
                }
                /*if (!inputFieldPlaceholder.isNullOrEmpty()) {
                val bringIntoViewRequester = remember { BringIntoViewRequester() }
                val coroutineScope = rememberCoroutineScope()
                Box(
                    Modifier.padding(top = 24.px).border(
                        1.px, JsMainTheme.colors.text_color_gray, RoundedCornerShape(6.px)
                    ).bringIntoViewRequester(bringIntoViewRequester)
                ) {

                    BasicTextField(
                        value = inputValue.value ?: "",
                        onValueChange = { inputValue.value = it },
                        textStyle = TextStyle(
                            color = JsMainTheme.colors.text_color_default,
                            fontWeight = FontWeight.Normal,
                            fontSize = 14.sp
                        ),
                        modifier = Modifier.fillMaxWidth()
                            .padding(start = 12.px, top = 8.px, end = 12.px, bottom = 8.px)
                            .onFocusIn {
                                coroutineScope.launch {
                                    bringIntoViewRequester.bringIntoView()
                                }
                            }
                    )
                    if (inputValue.value.isNullOrEmpty()) JsTextView(
                        inputFieldPlaceholder, 14,
                        textColor = JsMainTheme.colors.text_color_gray,
                        modifier = Modifier.align(Alignment.CenterStart)
                            .padding(start = 12.px)
                    )
                }
            }*/

                buttonsRow()
            }

            if (withCloseButton) JsImageView(
                "ic_close_white_24dp",
                tintColor = JsMainTheme.colors.app_main_color,
                modifier = Modifier.size(16.px).align(Alignment.TopEnd).padding(all = 16.px)
                    .clickable { onDismiss() }
            )
        }
    }
}