@Composable
fun JsButtonsMultiSelect(
    itemsFlow: StateFlow<List<MultiSelectItem>>,
    modifier: Modifier = Modifier,
    onClick: (MultiSelectItem) -> Unit
) {
    val itemsState = itemsFlow.collectAsState()
    Column(
        modifier = modifier,
        verticalArrangement = Arrangement.spacedBy(24.px),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Spacer(Modifier.size(24.px))
        itemsState.value.forEachIndexed { index, item ->
            val color = backgroundItemColor(itemsState.value.size, index)
            MultiSelectItem(item, color, onClick)
        }
        Spacer(Modifier.size(24.px))
    }
}

@Composable
private fun MultiSelectItem(
    item: MultiSelectItem,
    color: Color,
    onClick: (MultiSelectItem) -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxWidth(80.percent)
            .clipByCorner(30)
            .clickable { onClick.invoke(item) }
            .background(if (item.onSelected) color else JsMainTheme.colors.main_color_background)
            .border(
                if (item.onSelected) 0.px else 2.px,
                LineStyle.Solid,
                if (item.onSelected) color else color.copy(alpha = 0.5f)
            ),
    ) {
        Box(modifier = Modifier.fillMaxSize()) {
            if (item.onSelected) {
                JsImageView(
                    "ic_onboarding_select_accept",
                    modifier = Modifier
                        .padding(start = 24.px)
                        .align(Alignment.CenterStart)
                )
            }

            JsTextView(
                text = item.itemTitle,
                modifier = Modifier
                    .fillMaxWidth()
                    .align(Alignment.Center)
                    .padding(vertical = 12.px),
                textColor = JsMainTheme.colors.text_color_default,
                textSize = 15,
                fontWeight = FontWeight.Medium,
                textAlign = TextAlign.Center
            )
        }
    }
}

@Composable
fun backgroundItemColor(size: Int, position: Int): Color = when (position) {
    0 -> if (size > 2) JsMainTheme.colors.bg_color_onboarding_item_1 else JsMainTheme.colors.main_color_item_3
    1 -> if (size > 2) JsMainTheme.colors.bg_color_onboarding_item_2 else JsMainTheme.colors.app_main_color
    2 -> JsMainTheme.colors.bg_color_onboarding_item_3
    3 -> JsMainTheme.colors.bg_color_onboarding_item_4
    4 -> JsMainTheme.colors.bg_color_onboarding_item_5
    5 -> JsMainTheme.colors.bg_color_onboarding_item_6
    6 -> JsMainTheme.colors.bg_color_onboarding_item_7
    else -> JsMainTheme.colors.bg_color_onboarding_item_8

}