package managers

import androidx.compose.runtime.Composable
import dependencies.AccountRepository
import kotpref.models.StripeProduct
import kotpref.models.paywall.Billings
import kotpref.models.typeConverter.JsonObjectConverter

class BillingManager(val accountRepository: AccountRepository) : IBillingManager {

    companion object {
        private var productDetailsList = mutableListOf<StripeProduct>()
    }


    override fun startConnection() {

    }

    override fun getAllProductDetails(finishLoad: (List<ProductDetails>) -> Unit) {
        accountRepository.loadStripeProducts(
            onSuccess = { stripeProducts ->
                productDetailsList.clear()
                stripeProducts?.let { productDetailsList.addAll(it) }

                val list = mutableListOf<ProductDetails>()
                stripeProducts?.forEach { product ->
                    product.productId?.let {
                        val details = ProductDetails(
                            productDetails = PurchaseInfo(it), discountDetails = null
                        )
                        list.add(details)
                    }
                }
                finishLoad(list)
            },
            onError = { finishLoad(listOf()) }
        )
    }

    override fun getPurchaseDetails(callback: (List<PurchaseResult>) -> Unit, subsType: Boolean) {
        val result = mutableListOf<PurchaseResult>()
        productDetailsList
            .filter { subsType && Billings.isSubscribe(it.productId ?: "") }
            .forEach {
                val purchaseResult = PurchaseResult(
                    purchaseState = PurchaseState.PURCHASED,
                    isAcknowledged = true,
                    products = listOf(it.productId ?: ""),
                    purchaseToken = "",
                    orderId = it.priceId,
                    originalJson = JsonObjectConverter.objectToString(it) ?: ""
                )
                result.add(purchaseResult)
            }
        callback(result)
    }

    override fun getPurchaseHistory(callback: (List<PurchaseHistory>) -> Unit, subsType: Boolean) {

    }

    override fun getSubscribePrice(productId: String?): ProductInfo? {
        if (productId.isNullOrEmpty()) return null
        val stripeProduct =
            productDetailsList.firstOrNull { it.productId == productId } ?: return null
        return ProductInfo(
            productId = productId,
            priceAmountMicros = (stripeProduct.amount ?: 0).toLong() * 10_000L,
            priceCurrencyCode = (stripeProduct.currency ?: "").uppercase()
        )
    }

    override fun getProductId(purchases: List<PurchaseResult>): String? {
        return ""
    }

    override fun usedFreeTrial(history: List<PurchaseHistory>): Boolean {
        return false
    }

    @Composable
    override fun StripeByCardScreen(
        productId: String,
        onPurchase: (String, String?) -> Unit,
        onError: (String) -> Unit
    ) {
        val stripeProduct =
            productDetailsList.firstOrNull { it.productId == productId } ?: return

    }

    @Composable
    override fun StripeByAppleGoogleScreen(
        productId: String,
        onPurchase: (String, String?) -> Unit, onError: (String) -> Unit
    ) {
        val stripeProduct =
            productDetailsList.firstOrNull { it.productId == productId } ?: return

    }

}