package web.views.datePicker.picker

import androidx.compose.runtime.Composable
import androidx.compose.runtime.DisposableEffect
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.MutableState
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.rememberCoroutineScope
import androidx.compose.runtime.setValue
import com.varabyte.kobweb.compose.css.AlignItems
import com.varabyte.kobweb.compose.css.JustifyContent
import com.varabyte.kobweb.compose.css.Overflow
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.modifiers.alignItems
import com.varabyte.kobweb.compose.ui.modifiers.display
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxSize
import com.varabyte.kobweb.compose.ui.modifiers.height
import com.varabyte.kobweb.compose.ui.modifiers.id
import com.varabyte.kobweb.compose.ui.modifiers.justifyContent
import com.varabyte.kobweb.compose.ui.modifiers.overflow
import com.varabyte.kobweb.compose.ui.styleModifier
import com.varabyte.kobweb.compose.ui.toAttrs
import kotlinx.browser.document
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.launch
import org.jetbrains.compose.web.css.DisplayStyle
import org.jetbrains.compose.web.css.px
import org.jetbrains.compose.web.dom.Div
import org.w3c.dom.HTMLElement
import org.w3c.dom.INSTANT
import org.w3c.dom.SMOOTH
import org.w3c.dom.ScrollBehavior
import org.w3c.dom.ScrollToOptions
import org.w3c.dom.events.Event
import kotlin.math.abs
import kotlin.random.Random


@Composable
fun JsLazyColumn(
    itemsSize: Int,
    verticalPadding: Int,
    modifier: Modifier = Modifier.fillMaxSize(),
    currentVisibleItem: MutableState<Int>,
    startVisibleItem: Int,
    scrollEnabled: Boolean,
    onScrollStart: () -> Unit,
    onScrollFinished: (item: Int) -> Unit,
    content: @Composable (index: Int) -> Unit
) {
    val divId = remember { "scrollableListDiv-${Random.nextDouble()}" }
    var container by remember { mutableStateOf<HTMLElement?>(null) }
    val itemElements = remember { mutableMapOf<Int, HTMLElement>() }
    var hasInitialScrollBeenApplied by remember { mutableStateOf(false) }

    val scope = rememberCoroutineScope()
    var scrollJob: Job? by remember { mutableStateOf(null) }

    val snapToNearest: (HTMLElement, Map<Int, HTMLElement>) -> Unit = { div, items ->
        val startOffset = div.offsetTop
        val containerCenter = div.scrollTop + div.clientHeight / 2.0 + 1

        val closest = items.minByOrNull { (_, el) ->
            val elCenter = el.offsetTop - startOffset + el.offsetHeight / 2.0
            val abs = abs(containerCenter - elCenter)
            abs
        }

        closest?.let { (index, el) ->
            val targetScrollTop =
                el.offsetTop - (div.clientHeight / 2.0 - el.clientHeight / 2.0) - startOffset
            onScrollFinished(index)
            div.scrollTo(ScrollToOptions(top = targetScrollTop, behavior = ScrollBehavior.SMOOTH))
        }
    }

    DisposableEffect(Unit) {
        val divElement = document.getElementById(divId) as? HTMLElement
        if (divElement != null) {
            container = divElement
        }

        val onScroll: (Event) -> Unit = {
            val currentContainer = container
            if (currentContainer != null) {
                onScrollStart()
                scrollJob?.cancel()
                scrollJob = scope.launch {
                    delay(300)
                    snapToNearest(currentContainer, itemElements)
                }
            }
        }

        container?.addEventListener("scroll", onScroll)

        onDispose {
            container?.removeEventListener("scroll", onScroll)
            scrollJob?.cancel()
        }
    }

    LaunchedEffect(container) {
        val div = container ?: return@LaunchedEffect

        if (!hasInitialScrollBeenApplied && startVisibleItem >= 0 &&
            itemElements.containsKey(startVisibleItem)
        ) {
            val targetElement = itemElements[startVisibleItem]
            if (targetElement != null) {
                delay(100) // Give DOM time to render and calculate positions

                if (targetElement.offsetTop == 0 && targetElement.offsetHeight == 0) {
                    delay(100) // Retry if element position is not yet calculated
                    if (targetElement.offsetTop == 0) {
                        return@LaunchedEffect // Give up if still not positioned
                    }
                }

                val startOffset = div.offsetTop
                val targetScrollTop =
                    targetElement.offsetTop - (div.clientHeight / 2.0 - targetElement.clientHeight / 2.0) - startOffset
                div.scrollTo(
                    ScrollToOptions(top = targetScrollTop, behavior = ScrollBehavior.INSTANT)
                )
                hasInitialScrollBeenApplied = true
            }
        }
    }

    Div(
        attrs = modifier
            .id(divId)
            .overflow(Overflow.Auto)
            .styleModifier {
                property("scrollbar-width", "none")
                property("-ms-overflow-style", "none")
                property("scrollbar-color", "transparent transparent")
                property("-webkit-scrollbar", "none")
            }
            .toAttrs()
    ) {
        if (verticalPadding > 0) Div(attrs = Modifier.height(verticalPadding.px).toAttrs())

        repeat(itemsSize) { index ->
            Div(
                attrs = Modifier
                    .display(DisplayStyle.Flex)
                    .alignItems(AlignItems.Center)
                    .justifyContent(JustifyContent.Center)
                    .toAttrs {
                        ref { element ->
                            itemElements[index] = element as HTMLElement
                            onDispose { }
                        }
                    }
            ) { content(index) }
        }

        if (verticalPadding > 0) Div(attrs = Modifier.height(verticalPadding.px).toAttrs())
    }
}