//@Entity
@kotlinx.serialization.Serializable
data class AccountSubscription(
    //@ColumnInfo(name = "account_subscription_uuid")
    @SerialName("uuid") var uuid: String? = null,
    @SerialName("slug") var productId: String? = null,

    //@ColumnInfo(name = "account_subscription_type")
    @SerialName("type") var type: Int? = null,
    @SerialName("daily_profiles_view_count") var dailyProfilesViewCount: Int? = null,
    @SerialName("daily_wows_count") var dailyWowsCount: Int? = null,
    @SerialName("daily_chats_count") var dailyChatsCount: Int? = null,
    @SerialName("view_online_accounts") var viewOnlineAccounts: Boolean? = null,
    @SerialName("view_accounts_with_avatar") var viewAccountsWithAvatar: Boolean? = null,
    @SerialName("hidden_age") var hiddenAge: Boolean? = null,
    @SerialName("incognito_mode") var incognitoMode: Boolean? = null,
    @SerialName("full_region_filter") var fullRegionFilter: Boolean? = null,
    @SerialName("view_wows") var viewWows: Boolean? = null,
    @SerialName("hidden_location") var hiddenLocation: Boolean? = null,
    @SerialName("read_message_status") var readMessageStatus: Boolean? = null,

    //@ColumnInfo(name = "account_subscription_search_rate")
    @SerialName("search_rate") var searchRate: Int? = null
)