@Composable
fun JsPickerItem(
    text: String,
    selectIndex: Int,
    index: Int,
    rowCount: Int,
    itemHeight: Int,
) {
    Box(
        modifier = Modifier
            .height(itemHeight.px)
            /*.opacity(
                (calculateAnimatedAlpha(
                    lazyListState = lazyListState,
                    index = index,
                    rowCount = rowCount
                ) * 100).toInt().percent
            )*/,
        contentAlignment = Alignment.Center
    ) {
        JsTextView(
            text = text,
            fontWeight = FontWeight.Normal,
            textColor = JsMainTheme.colors.text_color_white,
            maxLines = 1,
            textSize = if (selectIndex == index) 20 else 18
        )
    }
}
