package web.helpers

import com.varabyte.kobweb.compose.css.AlignItems
import com.varabyte.kobweb.compose.css.CSSLengthOrPercentageNumericValue
import com.varabyte.kobweb.compose.css.JustifyContent
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.graphics.Color
import com.varabyte.kobweb.compose.ui.modifiers.alignItems
import com.varabyte.kobweb.compose.ui.modifiers.borderRadius
import com.varabyte.kobweb.compose.ui.modifiers.display
import com.varabyte.kobweb.compose.ui.modifiers.justifyContent
import com.varabyte.kobweb.compose.ui.modifiers.onClick
import com.varabyte.kobweb.compose.ui.modifiers.opacity
import com.varabyte.kobweb.compose.ui.modifiers.padding
import org.jetbrains.compose.web.css.DisplayStyle
import org.jetbrains.compose.web.css.px


fun Modifier.clipByCorner(roundedCorner: Int = 9999) = this.borderRadius(
    topLeft = roundedCorner.px,
    topRight = roundedCorner.px,
    bottomRight = roundedCorner.px,
    bottomLeft = roundedCorner.px
)

fun Modifier.alignCenter() = this.display(DisplayStyle.Flex)
    .justifyContent(JustifyContent.Center)
    .alignItems(AlignItems.Center)

fun Modifier.padding(
    start: CSSLengthOrPercentageNumericValue = 0.px,
    end: CSSLengthOrPercentageNumericValue = 0.px,
    top: CSSLengthOrPercentageNumericValue = 0.px,
    bottom: CSSLengthOrPercentageNumericValue = 0.px,
): Modifier = this.padding(left = start, right = end, top = top, bottom = bottom)

fun Modifier.padding(
    horizontal: CSSLengthOrPercentageNumericValue = 0.px,
    vertical: CSSLengthOrPercentageNumericValue = 0.px
): Modifier = this.padding(topBottom = vertical, leftRight = horizontal)

fun Modifier.clickable(
    callback: () -> Unit
): Modifier = this.onClick { callback.invoke() }

fun Modifier.alpha(
    alpha: Float
): Modifier = this.opacity(alpha)


fun Color.copy(alpha: Float): Color = this.toRgb().copyf(alpha = alpha)