package web.views.datePicker.picker

import androidx.compose.runtime.Composable
import androidx.compose.runtime.MutableState
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import com.varabyte.kobweb.compose.foundation.layout.Box
import com.varabyte.kobweb.compose.ui.Alignment
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.modifiers.height
import com.varabyte.kobweb.compose.ui.modifiers.padding
import kotlinx.datetime.LocalDate
import org.jetbrains.compose.web.css.px
import web.views.datePicker.PickerScrollState

@Composable
fun JsPickerYears(
    modifier: Modifier = Modifier,
    startItem: Int,
    today: LocalDate,
    scrollState: MutableState<PickerScrollState>,
    rowCount: Int,
    itemHeight: Int,
    selectorProperties: SelectorProperties,
    onScrollFinished: (years: String) -> Unit,
) {
    val minYear = today.year - 100
    val maxYear = today.year
    val items = (minYear..maxYear).toList()
    val startIndex = items.indexOf(startItem)

    Box(
        modifier = modifier
            .height((itemHeight * rowCount).px)
            .padding(leftRight = 8.px),
        contentAlignment = Alignment.Center
    ) {
        JsPickerScrollingDividers(selectorProperties, rowCount)

        val currentVisibleItem = remember { mutableStateOf(startIndex) }
        JsLazyColumn(
            itemsSize = items.size,
            verticalPadding = itemHeight * ((rowCount - 1) / 2),
            currentVisibleItem = currentVisibleItem,
            startVisibleItem = startIndex,
            scrollEnabled = scrollState.value == PickerScrollState.NON || scrollState.value == PickerScrollState.YEARS,
            onScrollStart = {
                scrollState.value = PickerScrollState.YEARS
            },
            onScrollFinished = { index ->
                scrollState.value = PickerScrollState.NON
                currentVisibleItem.value = index
                onScrollFinished(items[index % items.size].toString())
            }
        ) { index ->
            val actualIndex = index % items.size
            JsPickerItem(
                text = items[actualIndex].toString(),
                index = actualIndex,
                selectIndex = currentVisibleItem.value,
                rowCount = rowCount,
                itemHeight = itemHeight
            )
        }
    }
}