enum class PaywallType { Settings, Paywall, Subscriptions, Discount }

enum class AdaptyCustomParams {
    app_version,
    user_gender,
    beta_subscriptions,
    people_screen_type,
    people_screen_swipes_priority,
    people_screen_block_default,
    paywall_with_extra_trial,
    paywall_with_extra_discount,
    register_by_email,
    email_verification_time
}

data class AdaptyCustomParameter(
    var adaptyCustomParameter: AdaptyCustomParams,
    var intValue: Int? = null,
    var stringValue: String? = null
)

@Suppress("EXPECT_ACTUAL_CLASSIFIERS_ARE_IN_BETA_WARNING")
expect class AdaptyManager {

    fun updateProfile(account: Account, onFinish: () -> Unit = {})
    fun updateCustomParameter(
        parameter: AdaptyCustomParams, value: String, onFinish: () -> Unit = {}
    )

    fun updateCustomParameters(
        parameters: List<AdaptyCustomParameter>, onFinish: () -> Unit = {}
    )

    fun sendBoughtSubscriptionInfo(orderId: String)

    fun getPaywall(
        paywallType: PaywallType,
        onSuccess: (Any?) -> Unit,
        onError: (String?) -> Unit = {}
    )

    fun logShowPaywall(paywallType: PaywallType)
}