package dependencies

import kotlinx.browser.document
import org.w3c.dom.HTMLElement
import kotlin.js.Promise
import kotlin.js.collections.JsArray


enum class WebContainer(val screenName: String) {
    PaymentScreen("payment-screen"),
    PaymentChooser("payment-chooser"),
    CaptchaScreen("captcha-screen"),
    StartLoader("loader-container"),
}

const val stripeInterop = "./stripeInterop.js"

@JsModule(stripeInterop)
external object StripeInterop {
    fun initStripe(publicKey: String)
    fun createPaymentMethod(): Promise<String?>
    fun payWithGoogleOrApple(
        amountInCents: Int,
        currency: String,
        countryCode: String,
        label: String,
        onGooglePay: (String) -> Unit,
        onApplePay: (String) -> Unit
    ): Promise<Any?>

    fun triggerGooglePay()
    fun triggerApplePay()
}

const val recaptchaInterop = "./recaptchaInterop.js"

@JsModule(recaptchaInterop)
external object RecaptchaInterop {
    fun setupRecaptcha(containerId: String, siteKey: String): Int
    fun initRecaptchaCallback(callback: (String) -> Unit)
}


const val databaseInterop = "./databaseInterop.js"

@JsModule(databaseInterop)
external object DatabaseInterop {
    fun saveItem(dbName: String, storeName: String, item: Any): Promise<Boolean>
    fun getAllItems(dbName: String, storeName: String): Promise<Array<String>>
    fun deleteItem(dbName: String, storeName: String, id: String): Promise<Boolean>
    fun deleteDb(dbName: String): Promise<Boolean>

    fun parseJson(text: String): Any
    fun toJson(obj: Any): String
}


const val galleryInterop = "./galleryInterop.js"
const val cameraInterop = "./cameraInterop.js"
typealias OnImageSuccessCallback = (String) -> Unit
typealias OnErrorCallback = (String) -> Unit

@JsModule(galleryInterop)
external object GalleryInterop {
    fun selectImage(onSuccess: OnImageSuccessCallback, onError: OnErrorCallback)
}

@JsModule(cameraInterop)
external object CameraInterop {
    fun takePhoto(onSuccess: OnImageSuccessCallback, onError: OnErrorCallback)
}


fun showWebContainer(container: WebContainer) {
    //val container = document.querySelector(".container") as? HTMLElement
    //container?.style?.display = "block"
    val target = document.getElementById(container.screenName) as? HTMLElement
    target?.classList?.add("visible")
    //document.querySelector(".container")?.classList?.add("visible")
}

fun hideWebContainer(container: WebContainer) {
    val target = document.getElementById(container.screenName) as? HTMLElement
    target?.classList?.remove("visible")
    //document.querySelector(".container")?.classList?.remove("visible")

//    val container = document.querySelector(".container") as? HTMLElement
//    container?.style?.display = "none"

//    document.getElementById("card-element")?.remove()
}