package kotpref.models.account

import kotlinx.serialization.SerialName
import kotlinx.serialization.json.JsonObject

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-04-11.
 */
//@Entity
@kotlinx.serialization.Serializable
data class AccountInfo(

    @SerialName("about") var about: String? = null,

    @SerialName("pronounce") var pronounce: Int? = null,
    @SerialName("work") var work: Int? = null,
    @SerialName("education") var education: Int? = null,
    @SerialName("accommodation") var accommodation: Int? = null,
    @SerialName("kids") var kids: Int? = null,
    @SerialName("birthday") var birthday: String? = null,

    //@TypeConverters(JsonObjectConverter::class)
    @SerialName("compatibility_answers") var compatibilityAnswers: JsonObject? = null,

    @SerialName("i_am")
    //@TypeConverters(ListIntConverter::class)
    var iamList: MutableList<Int>? = null,

    @SerialName("interested_in")
    //@TypeConverters(ListIntConverter::class)
    var interestedIn: MutableList<Int>? = null,

    @SerialName("looking_for")
    //@TypeConverters(ListIntConverter::class)
    var lookingFor: MutableList<Int>? = null,

    @SerialName("relationship_status")
    var relationshipStatus: Int? = null,

    @SerialName("position")
    var sexPosition: String? = null,

    @SerialName("interests")
    //@TypeConverters(ListStringConverter::class)
    var interests: MutableList<String>? = null,

    @SerialName("music")
    //@TypeConverters(ListStringConverter::class)
    var music: MutableList<String>? = null,


    /** Account parameters **/
    @SerialName("height") var height: Double? = null,
    @SerialName("weight") var weight: Double? = null,
    @SerialName("figure_type") var figureType: Int? = null,
    @SerialName("hair_color") var hairColor: Int? = null,
    @SerialName("eye_color") var eyeColor: Int? = null,


    /** Account health **/
    @SerialName("last_test") var date: String? = null,
    @SerialName("hiv") var hiv: Int? = null,
    @SerialName("venereal_diseases") var veneral: Int? = null
)